int heap_size = 0;

void heap_push(long long d, int v) {
    int i = heap_size++;
    heap[i].d = d;
    heap[i].v = v;
    // sift up
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].d > heap[i].d) {
            HeapNode tmp = heap[p];
            heap[p] = heap[i];
            heap[i] = tmp;
            i = p;
        } else break;
    }
}

HeapNode heap_pop() {
    HeapNode ret = heap[0];
    heap[0] = heap[--heap_size];
    int i = 0;
    while (1) {
        int l = 2*i+1, r = 2*i+2, m = i;
        if (l < heap_size && heap[l].d < heap[m].d) m = l;
        if (r < heap_size && heap[r].d < heap[m].d) m = r;
        if (m == i) break;
        HeapNode tmp = heap[m];
        heap[m] = heap[i];
        heap[i] = tmp;
        i = m;
    }
    return ret;
}

