#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_NODES 10000
#define INF INT_MAX

// Structure for adjacency list node
typedef struct Edge {
    int to;
    int weight;
    struct Edge* next;
} Edge;

// Graph structure
typedef struct {
    Edge* head[MAX_NODES];
    int num_nodes;
} Graph;

// Min-heap node for Dijkstra
typedef struct {
    int vertex;
    int dist;
} HeapNode;

// Min-heap structure
typedef struct {
    HeapNode* arr[MAX_NODES];
    int size;
} MinHeap;

// Function prototypes
void init_graph(Graph* g, int n);
void add_edge(Graph* g, int u, int v, int w);
void min_heap_push(MinHeap* heap, int vertex, int dist);
HeapNode* min_heap_pop(MinHeap* heap);
void heapify_up(MinHeap* heap, int idx);
void heapify_down(MinHeap* heap, int idx);
void dijkstra(Graph* g, int source, int dist[]);

int main() {
    int n, m, r;
    scanf("%d %d %d", &n, &m, &r);

    Graph g;
    init_graph(&g, n);

    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        add_edge(&g, u, v, w);
    }

    int dist[MAX_NODES];
    dijkstra(&g, r, dist);

    for (int i = 0; i < n; i++) {
        if (dist[i] == INF) {
            printf("INF\n");
        } else {
            printf("%d\n", dist[i]);
        }
    }

    return 0;
}

void init_graph(Graph* g, int n) {
    g->num_nodes = n;
    for (int i = 0; i < n; i++) {
        g->head[i] = NULL;
    }
}

void add_edge(Graph* g, int u, int v, int w) {
    Edge* new_edge = (Edge*)malloc(sizeof(Edge));
    new_edge->to = v;
    new_edge->weight = w;
    new_edge->next = g->head[u];
    g->head[u] = new_edge;
}

void min_heap_push(MinHeap* heap, int vertex, int dist) {
    HeapNode* node = (HeapNode*)malloc(sizeof(HeapNode));
    node->vertex = vertex;
    node->dist = dist;

    int i = heap->size;
    heap->arr[i] = node;
    heap->size++;
    heapify_up(heap, i);
}

HeapNode* min_heap_pop(MinHeap* heap) {
    if (heap->size == 0) return NULL;

    HeapNode* min_node = heap->arr[0];
    heap->size--;
    heap->arr[0] = heap->arr[heap->size];
    heapify_down(heap, 0);

    return min_node;
}

void heapify_up(MinHeap* heap, int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap->arr[parent]->dist <= heap->arr[idx]->dist) break;

        HeapNode* temp = heap->arr[parent];
        heap->arr[parent] = heap->arr[idx];
        heap->arr[idx] = temp;

        idx = parent;
    }
}

void heapify_down(MinHeap* heap, int idx) {
    int smallest = idx;
    int left = 2 * idx + 1;
    int right = 2 * idx + 2;

    if (left < heap->size && heap->arr[left]->dist < heap->arr[smallest]->dist)
        smallest = left;
    if (right < heap->size && heap->arr[right]->dist < heap->arr[smallest]->dist)
        smallest = right;

    if (smallest != idx) {
        HeapNode* temp = heap->arr[smallest];
        heap->arr[smallest] = heap->arr[idx];
        heap->arr[idx] = temp;
        heapify_down(heap, smallest);
    }
}

void dijkstra(Graph* g, int source, int dist[]) {
    int n = g->num_nodes;

    // Initialize distances
    for (int i = 0; i < n; i++) {
        dist[i] = INF;
    }
    dist[source] = 0;

    MinHeap heap;
    heap.size = 0;

    min_heap_push(&heap, source, 0);

    while (heap.size > 0) {
        HeapNode* current = min_heap_pop(&heap);
        int u = current->vertex;
        int d = current->dist;
        free(current);

        // Skip if we have already found a better path
        if (d > dist[u]) continue;

        Edge* edge = g->head[u];
        while (edge != NULL) {
            int v = edge->to;
            int w = edge->weight;

            if (dist[u] != INF && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                min_heap_push(&heap, v, dist[v]);
            }
            edge = edge->next;
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

typedef struct Edge {
    int to;
    int w;
    int next;
} Edge;

typedef struct HeapNode {
    int v;
    ll d;
} HeapNode;

typedef struct MinHeap {
    HeapNode *a;
    int size;
    int cap;
} MinHeap;

void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 1));
    h->size = 0;
    h->cap = cap;
}

void heap_push(MinHeap *h, int v, ll d) {
    if (h->size + 1 > h->cap) {
        h->cap *= 2;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->size;
    while (i > 1 && h->a[i / 2].d > d) {
        h->a[i] = h->a[i / 2];
        i /= 2;
    }
    h->a[i].v = v;
    h->a[i].d = d;
}

HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->size--];

    int i = 1, child;
    while ((i * 2) <= h->size) {
        child = i * 2;
        if (child + 1 <= h->size && h->a[child + 1].d < h->a[child].d) child++;
        if (h->a[child].d >= last.d) break;
        h->a[i] = h->a[child];
        i = child;
    }
    h->a[i] = last;
    return ret;
}

int heap_empty(MinHeap *h) {
    return h->size == 0;
}

int main(void) {
    int V, E, r;
    if (scanf("%d %d %d", &V, &E, &r) != 3) return 0;

    int *head = (int *)malloc(sizeof(int) * V);
    for (int i = 0; i < V; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * E);
    for (int i = 0; i < E; i++) {
        int s, t, d;
        scanf("%d %d %d", &s, &t, &d);
        edges[i].to = t;
        edges[i].w = d;
        edges[i].next = head[s];
        head[s] = i;
    }

    const ll INF = (1LL << 60);
    ll *dist = (ll *)malloc(sizeof(ll) * V);
    for (int i = 0; i < V; i++) dist[i] = INF;
    dist[r] = 0;

    MinHeap heap;
    heap_init(&heap, E + 1);
    heap_push(&heap, r, 0);

    while (!heap_empty(&heap)) {
        HeapNode cur = heap_pop(&heap);
        int v = cur.v;
        ll d = cur.d;

        if (d != dist[v]) continue;

        for (int ei = head[v]; ei != -1; ei = edges[ei].next) {
            int to = edges[ei].to;
            ll nd = d + edges[ei].w;
            if (nd < dist[to]) {
                dist[to] = nd;
                heap_push(&heap, to, nd);
            }
        }
    }

    for (int i = 0; i < V; i++) {
        if (dist[i] == INF) {
            printf("INF\n");
        } else {
            printf("%lld\n", dist[i]);
        }
    }

    free(head);
    free(edges);
    free(dist);
    free(heap.a);

    return 0;
}

